    getDeptIdsNodes: function getDeptIdsNodes(nodes, deptId, deptIdsArr) {
      var _this4 = this;

      nodes.forEach(function (item) {
        //利用foreach循环遍历
        if (item.pId == deptId) {
          //判断递归结束条件
          deptIdsArr.push(item.deptId);

          _this4.getDeptIdsNodes(_this4.indexDeptData, item.deptId, deptIdsArr); //递归调用                      

        }
      });
      return deptIdsArr;
    },
