    //暂停
    suspendData: function suspendData(row) {
      var _this = this;

      var kProcessname = row.kProcessname;
      var params = {};
      params.kProcessname = kProcessname;
      params.status = "paused";
      this.$confirm("确定暂停?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        platformParameterSet.getHeartbeatApi(params).then(function (response) {
          if (response.data.data.status == 0) {
            _this.$message({
              message: '成功',
              type: 'success'
            });

            _this.onSubmit("formInline", false);
          } else {
            _this.$message({
              message: '失败',
              type: 'danger'
            });
          }
        });
      }).catch(function () {});
    },
    //开始
    beginData: function beginData(row) {
      var _this2 = this;

      var kProcessname = row.kProcessname;
      var params = {};
      params.kProcessname = kProcessname;
      params.status = "running";
      this.$confirm("确定开始?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        platformParameterSet.getHeartbeatApi(params).then(function (response) {
          if (response.data.data.status == 0) {
            _this2.$message({
              message: '成功',
              type: 'success'
            });

            _this2.onSubmit("formInline", false);
          } else {
            _this2.$message({
              message: '失败',
              type: 'danger'
            });
          }
        });
      }).catch(function () {});
    },
    checkStatus: function checkStatus(index, row) {
      var _this3 = this;

      var kProcessname = row.kProcessname;
      var params = {};
      params.kProcessname = kProcessname;
      platformParameterSet.getHeartbeatApi(params).then(function (response) {
        if (response.data.nodeHeartbeatUrl != null) {
          if (response.data.data.status == 0) {
            if (response.data.data.data == "running") {
              _this3.tableData[index].engineStatus = "正常";
            } else if (response.data.data.data == "pausing") {
              _this3.tableData[index].engineStatus = "暂停中";
            } else if (response.data.data.data == "paused") {
              _this3.tableData[index].engineStatus = "暂停";
            }
          } else {
            _this3.tableData[index].engineStatus = "异常";
          }
        }

        ;
        var result = "";

        if (response.data.data != null) {
          if (response.data.data.status == 0) {
            result = response.data.data.data;

            if (result == "running") {
              result = "正常";
            } else if (result == "pausing") {
              result = "暂停中";
            } else if (result == "paused") {
              result = "暂停";
            }
          } else {
            result = "异常";
          }
        } else {
          result = "未知";
        }

        _this3.$alert(result, '引擎状态', {
          confirmButtonText: '确定',
          callback: function callback(action) {}
        });
      });
    },
