    treeRecursion: function treeRecursion(treeData) {
      if (treeData.length > 0) {
        for (var i = 0; i < treeData.length; i++) {
          if (treeData[i].children.length > 0) {
            this.treeRecursion(treeData[i].children);
          }

          if (treeData[i].id == this.nodeData.id) {
            if (this.isFile == true) {
              treeData[i].label = this.fileEditCount.fileEditDicName + "." + this.fileEditCount.fileEditDicType;
              treeData[i].fileContent = this.fileEditCount.fileContent;
              treeData[i].fileType = this.fileEditCount.fileEditDicType;

              if (this.fileEditCount.fileContent != null) {
                var size = filters_common["a" /* default */].accDiv(this.fileEditCount.fileContent.length, 1024);
                treeData[i].fileSize = size.toFixed(2).toString() + "KB";
              }
            } else {
              treeData[i].label = this.fileEditCount.fileEditDicName;
              treeData[i].createTime = this.getCurrentTime();
            }
          }
        }
      }
    },
